challenge.solution:
function throttle(fn, wait) {
  let last = -Infinity;
  return function (...args) {
    const now = performance.now();
    if (now - last >= wait) {
      last = now;
      return fn.apply(this, args);
    }
  };
}
// 首次立即执行；窗口内忽略；不补发尾调用。

