  const stats = { cold: [], warm: [], incremental: [] };
  for (const row of rows) {
    if (Object.hasOwn(stats, row.kind) && Number.isFinite(row.ms) && row.ms >= 0) stats[row.kind].push(row.ms);
  }
  return Object.fromEntries(Object.entries(stats).map(([kind, values]) => [kind, values.length ? values.reduce((a, b) => a + b, 0) / values.length : null]));
}

